1	//! `push` subcommand — collapse the dual-repo commit+push+
2	//! squash-push ceremony into a single command.
3	//!
4	//! See `notes/chores/chores-05.md > Add push subcommand (0.37.0)` for the
5	//! original design.
6	//!
7	//! The run is a straight line: review -> message -> commit-work ->
8	//! commit-bot -> bookmark-set -> push-work -> squash-push-bot. There
9	//! is no saved state and no resume, because a recorded position
10	//! describes a world that may have changed for reasons push cannot
11	//! know. What push owes instead is that **rerunning is always
12	//! safe**: every stage checks its own precondition and no-ops when
13	//! its work is already done, so a rerun after a failure is simply a
14	//! run.
15	//!
16	//! Failures before `push-work` are rolled back from `jj op`
17	//! snapshots taken moments earlier in this same process. Failures
18	//! from `push-work` on have crossed the remote boundary — push
19	//! stops and reports, and putting the repos right is the user's
20	//! call, not something a tool can infer.
21	
22	use std::fs;
23	use std::io::IsTerminal;
24	use std::path::{Path, PathBuf};
25	
26	use clap::Args;
27	use log::{debug, info, warn};
28	
29	use crate::common::{prompt, run};
30	use crate::context::Context;
31	use crate::jj;
32	use crate::options_flags::squash::SquashSpec;
33	use crate::subcommand::SubcommandRunner;
34	use crate::sync::{current_op_id, op_restore};
35	
36	/// Bookmark the bot (`.claude`) repo always advances and
37	/// pushes. The bot repo is a linear journal on `main` by
38	/// design — `<bookmark>` names a work-repo bookmark only.
39	const BOT_BOOKMARK: &str = "main";
40	
41	/// CLI arguments for the `push` subcommand.
42	///
43	/// Flag set mirrors the design in `notes/chores/chores-05.md`. Flags are
44	/// parsed in 0.37.0-0; their real effects land across the remaining
45	/// 0.37.0-N steps. See the module docstring for which flags activate
46	/// when.
47	#[derive(Args, Debug)]
48	pub struct PushArgs {
49	    /// Bookmark to advance in the work repo (positional form of
50	    /// `--bookmark`). The bot repo always advances `main`.
51	    ///
52	    /// Accepting a positional lets the common case read as `vc-x1 push main`
53	    /// without the `--bookmark` ceremony; `--bookmark` is kept as an
54	    /// alias for scripts and for composition with other args. The two
55	    /// forms conflict if both supplied.
56	    #[arg(value_name = "BOOKMARK", conflicts_with = "bookmark")]
57	    pub bookmark_pos: Option<String>,
58	
59	    /// Bookmark to advance in the work repo (flag form; see positional).
60	    #[arg(long, conflicts_with = "bookmark_pos")]
61	    pub bookmark: Option<String>,
62	
63	    /// Pause between every stage for an interactive approval gate.
64	    #[arg(long)]
65	    pub step: bool,
66	
67	    /// Stop before `squash-push-bot` so it can be run manually.
68	    #[arg(long)]
69	    pub no_squash_push: bool,
70	
71	    /// Print the exact commands for every stage without side effects.
72	    #[arg(long)]
73	    pub dry_run: bool,
74	
75	    /// Commit title (skip `$EDITOR` for the message stage).
76	    #[arg(long, value_name = "STR")]
77	    pub title: Option<String>,
78	
79	    /// Commit body (skip `$EDITOR` for the message stage).
80	    #[arg(long, value_name = "STR")]
81	    pub body: Option<String>,
82	
83	    /// Auto-approve interactive prompts (review gate, message-edit
84	    /// confirmation). Required when `--title` / `--body` aren't both
85	    /// supplied in non-interactive contexts.
86	    #[arg(short = 'y', long)]
87	    pub yes: bool,
88	}
89	
90	/// Inputs to the push op, flat, owned, clap-free.
91	///
92	/// Mirrors `PushArgs`, with the two clap bookmark spellings
93	/// (positional `BOOKMARK` and `--bookmark`) collapsed into one
94	/// `bookmark` field. The rest map straight over: `step`,
95	/// `no_squash_push`, `dry_run`, `title`, `body`, `yes`.
96	pub struct PushParams {
97	    pub bookmark: Option<String>,
98	    pub step: bool,
99	    pub no_squash_push: bool,
100	    pub dry_run: bool,
101	    pub title: Option<String>,
102	    pub body: Option<String>,
103	    pub yes: bool,
104	}
105	
106	/// What the message stage resolves and the later stages consume.
107	///
108	/// Lives for one run in one process — the deliberate replacement
109	/// for the persisted `PushState`. Both chids are captured before
110	/// any commit happens, so each repo's `ochid:` trailer can name the
111	/// other side's change.
112	struct Run {
113	    title: String,
114	    body: String,
115	    /// Chid of the work-repo change this run publishes: `@` when the
116	    /// working copy has changes (it becomes `@-` once committed),
117	    /// else the existing `@-`.
118	    work_chid: String,
119	    /// Same rule on the bot side.
120	    bot_chid: String,
121	    /// Whether the bot working copy had changes — decides whether
122	    /// `commit-bot` runs.
123	    bot_had_changes: bool,
124	}
125	
126	/// `jj op` ids captured immediately before the first mutation, used
127	/// to restore both repos if a pre-remote stage fails.
128	pub(crate) struct Snapshots {
129	    pub(crate) work: String,
130	    pub(crate) bot: String,
131	}
132	
133	impl From<&PushArgs> for PushParams {
134	    /// Convert clap-derived `PushArgs` into the flat `PushParams`,
135	    /// collapsing `bookmark_pos` / `bookmark` (clap already enforces
136	    /// they don't both appear) into the single `bookmark` field.
137	    fn from(a: &PushArgs) -> Self {
138	        Self {
139	            bookmark: a.bookmark_pos.clone().or_else(|| a.bookmark.clone()),
140	            step: a.step,
141	            no_squash_push: a.no_squash_push,
142	            dry_run: a.dry_run,
143	            title: a.title.clone(),
144	            body: a.body.clone(),
145	            yes: a.yes,
146	        }
147	    }
148	}
149	
150	impl SubcommandRunner for PushArgs {
151	    type Params = PushParams;
152	
153	    /// Delegate to the existing `From<&PushArgs>` impl above
154	    /// (total — never fails).
155	    fn to_params(&self) -> Result<Self::Params, String> {
156	        Ok(PushParams::from(self))
157	    }
158	
159	    /// Run the existing `push` op.
160	    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
161	        push(ctx, params)
162	    }
163	}
164	
165	/// Whether `stdin` is attached to a terminal.
166	///
167	/// Interactive prompts (`stage_review`, `$EDITOR` launch in
168	/// `stage_message`, `--step` gates) need this to fail fast in
169	/// scripted / CI contexts instead of hanging on `read_line`.
170	/// `--yes` overrides the check — script callers opt in by
171	/// asserting "all prompts auto-approved".
172	fn is_stdin_tty() -> bool {
173	    std::io::stdin().is_terminal()
174	}
175	
176	/// Entry point for the `push` subcommand.
177	///
178	/// 0.37.0-5 behavior: interactive flow with two approval gates
179	/// (review + message) plus polish flags: `--dry-run` prints what
180	/// would run without side effects, `--step` pauses between every
181	/// stage, non-tty stdin fails fast when prompts are required,
182	/// `--yes` opts out of all prompts. On any failure in stages 4-6
183	/// (the local mutation window between `commit-work` and
184	/// `bookmark-set`), both repos roll back to the `jj op` snapshot
185	/// recorded at the start of `commit-work`. After `push-work` the
186	/// remote boundary is crossed and recovery is forward-only.
187	///
188	/// `ctx` supplies the repo sessions the mutation stages run their
189	/// verbs on (`Context::session`, one open per repo for the whole
190	/// run).
191	pub fn push(ctx: &mut Context, params: &PushParams) -> Result<(), Box<dyn std::error::Error>> {
192	    let cwd = std::env::current_dir()?;
193	    push_in(ctx, &cwd, params)
194	}
195	
196	/// `push` parameterized on the workspace root. CLI dispatch calls
197	/// this with `std::env::current_dir()`; integration tests call it
198	/// with a fixture tempdir so the stages mutate the fixture's repos
199	/// instead of the developer's working tree.
200	///
201	/// The stages run in a straight line. The mutation window
202	/// (`commit-work` -> `bookmark-set`) is wrapped so a failure inside
203	/// it restores both repos from snapshots taken just before it;
204	/// after `push-work` the remote boundary is crossed and a failure
205	/// simply propagates.
206	pub(crate) fn push_in(
207	    ctx: &mut Context,
208	    workspace_root: &Path,
209	    params: &PushParams,
210	) -> Result<(), Box<dyn std::error::Error>> {
211	    if params.dry_run {
212	        info!("push: DRY-RUN — no side effects (no commits, no pushes)");
213	    }
214	
215	    let bookmark = params.bookmark.as_deref().ok_or(
216	        "push: a bookmark is required — pass it as a positional \
217	         (`vc-x1 push main`) or via `--bookmark main`",
218	    )?;
219	
220	    stage_review(workspace_root, params)?;
221	    step_gate(params, "review", "message")?;
222	
223	    let run = stage_message(workspace_root, params)?;
224	    step_gate(params, "message", "commit-work")?;
225	
226	    // Snapshot both repos before the first mutation. Dry-runs
227	    // mutate nothing, so they need no rollback target.
228	    let snapshots = if params.dry_run {
229	        None
230	    } else {
231	        Some(Snapshots {
232	            work: current_op_id(workspace_root)?,
233	            bot: current_op_id(&bot_path(workspace_root)?)?,
234	        })
235	    };
236	
237	    if let Err(e) = mutate(ctx, workspace_root, bookmark, &run, params) {
238	        if let Some(snapshots) = &snapshots {
239	            rollback_on_failure(workspace_root, snapshots, e.as_ref());
240	        }
241	        return Err(e);
242	    }
243	
244	    stage_push_work(ctx, workspace_root, bookmark, params)?;
245	
246	    if params.no_squash_push {
247	        info!("push squash-push-bot: skip (--no-squash-push)");
248	    } else {
249	        step_gate(params, "push-work", "squash-push-bot")?;
250	        stage_squash_push_bot(ctx, workspace_root, params)?;
251	    }
252	
253	    if params.dry_run {
254	        info!("push: DRY-RUN complete — no changes written");
255	        return Ok(());
256	    }
257	
258	    // Honest completion: confirm the world matches what the stages
259	    // claim to have done. Catches the 0.37.1 false-success symptom.
260	    // Warning-only — work has crossed the remote boundary by now, so
261	    // rollback isn't sound and the user needs to investigate.
262	    match verify_completion(workspace_root, bookmark, &run) {
263	        Ok(()) => info!("push: completed all stages (verified)"),
264	        Err(e) => {
265	            warn!("push: completed stages but post-completion verification failed:");
266	            warn!("  {e}");
267	            warn!("  investigate the discrepancy before the next push");
268	        }
269	    }
270	    Ok(())
271	}
272	
273	/// The rollback-eligible window: everything that mutates a repo
274	/// before anything reaches a remote.
275	fn mutate(
276	    ctx: &mut Context,
277	    root: &Path,
278	    bookmark: &str,
279	    run: &Run,
280	    params: &PushParams,
281	) -> Result<(), Box<dyn std::error::Error>> {
282	    stage_commit_work(ctx, root, run, params)?;
283	    step_gate(params, "commit-work", "commit-bot")?;
284	    stage_commit_bot(ctx, root, run, params)?;
285	    step_gate(params, "commit-bot", "bookmark-set")?;
286	    stage_bookmark_set(ctx, root, bookmark, params)?;
287	    step_gate(params, "bookmark-set", "push-work")?;
288	    Ok(())
289	}
290	
291	/// `--step`: pause between stages so the user can inspect the
292	/// repos before the next one runs.
293	///
294	/// Skipped entirely without `--step`, and under `--yes` or a
295	/// non-tty stdin the prompt would hang, so `--yes` bypasses it and
296	/// a non-tty without `--yes` is an error rather than a hang.
297	fn step_gate(
298	    params: &PushParams,
299	    done: &str,
300	    next: &str,
301	) -> Result<(), Box<dyn std::error::Error>> {
302	    if !params.step {
303	        return Ok(());
304	    }
305	    if params.yes {
306	        debug!("push step: --yes skips step gate between {done} and {next}");
307	        return Ok(());
308	    }
309	    if !is_stdin_tty() {
310	        return Err("push: --step requires a tty (stdin is not interactive); \
311	                    add --yes to bypass step gates in non-interactive contexts"
312	            .into());
313	    }
314	    let answer = prompt(&format!(
315	        "push step: {done} done. Continue to {next}? [y/N] "
316	    ))?;
317	    let normalized = answer.trim().to_ascii_lowercase();
318	    if normalized != "y" && normalized != "yes" {
319	        return Err(format!("push: step gate declined after {done} (got {answer:?})").into());
320	    }
321	    Ok(())
322	}
323	
324	/// Full path of the bot repo for a given workspace root, resolved
325	/// from `.vc-config.toml`'s `repos.bot` (push requires a dual
326	/// workspace). Also the dual-mode entry preflight: resolution
327	/// verifies both repos' recorded topology agrees and errors loudly
328	/// — with everything known, changing nothing — when it doesn't.
329	fn bot_path(workspace_root: &Path) -> Result<PathBuf, Box<dyn std::error::Error>> {
330	    crate::common::require_bot_dir(workspace_root)
331	}
332	
333	/// Restore both repos to their `jj op` snapshots.
334	///
335	/// Best-effort — if the restore itself fails we warn but don't
336	/// shadow the original error the caller will propagate. Exposed at
337	/// `pub(crate)` so integration tests can exercise the rollback path
338	/// directly rather than forcing a stage failure.
339	pub(crate) fn rollback_on_failure(
340	    root: &Path,
341	    snapshots: &Snapshots,
342	    original: &dyn std::error::Error,
343	) {
344	    warn!("push: rolling back both repos after: {original}");
345	    match op_restore(root, &snapshots.work) {
346	        Ok(()) => info!("push: restored work repo to op {}", snapshots.work),
347	        Err(e) => warn!("push: work repo restore failed: {e}"),
348	    }
349	    // Rollback is best-effort inside an error path — a failed
350	    // bot-dir resolution is reported, not propagated.
351	    match bot_path(root) {
352	        Ok(bot) => match op_restore(&bot, &snapshots.bot) {
353	            Ok(()) => info!("push: restored bot repo to op {}", snapshots.bot),
354	            Err(e) => warn!("push: bot repo restore failed: {e}"),
355	        },
356	        Err(e) => warn!("push: bot repo restore skipped (unresolvable): {e}"),
357	    }
358	}
359	
360	/// Review: first approval gate — "is the work done right?".
361	///
362	/// Shows a `jj diff --stat` of the pending changes in both repos
363	/// and prompts the user to continue. `--yes` short-circuits the
364	/// prompt (required for scripted / non-tty use). In `--dry-run`
365	/// the diff is still shown (that's the point of dry-run — see
366	/// what *would* be reviewed) but approval is auto-granted.
367	fn stage_review(root: &Path, params: &PushParams) -> Result<(), Box<dyn std::error::Error>> {
368	    let bot = bot_path(root)?;
369	    let work_arg = root.to_string_lossy();
370	    let bot_arg = bot.to_string_lossy();
371	    info!("push review: pending changes:");
372	    info!("  work ({work_arg}):");
373	    let work_stat = run("jj", &["diff", "--stat", "-R", &work_arg], root)?;
374	    for line in work_stat.lines() {
375	        info!("    {line}");
376	    }
377	    info!("  .claude ({bot_arg}):");
378	    let bot_stat = run("jj", &["diff", "--stat", "-R", &bot_arg], root)?;
379	    for line in bot_stat.lines() {
380	        info!("    {line}");
381	    }
382	    if params.yes {
383	        info!("push review: auto-approved (--yes)");
384	        return Ok(());
385	    }
386	    if params.dry_run {
387	        info!("push review: [dry-run] auto-approved");
388	        return Ok(());
389	    }
390	    if !is_stdin_tty() {
391	        return Err("push review: stdin is not a tty; \
392	                    pass --yes to auto-approve in non-interactive contexts"
393	            .into());
394	    }
395	    let answer = prompt("push review: approve and continue to message stage? [y/N] ")?;
396	    let normalized = answer.trim().to_ascii_lowercase();
397	    if normalized == "y" || normalized == "yes" {
398	        Ok(())
399	    } else {
400	        Err(format!(
401	            "push review: declined (got {answer:?}); re-run with --yes or confirm with 'y'"
402	        )
403	        .into())
404	    }
405	}
406	
407	/// Message: resolve the commit message and capture both repos'
408	/// pre-commit changeIDs, so each side's `ochid:` trailer can name
409	/// the other.
410	///
411	/// Title/body come from `--title`/`--body`, else `$EDITOR`. There
412	/// is no persisted message to fall back on: a rerun supplies the
413	/// flags again or opens the editor again, which is the cost of
414	/// having no state file and a cheap one — the message is in the
415	/// user's scrollback either way.
416	///
417	/// When neither repo has pending changes, no commit will be made on
418	/// either side, so an absent message is not an error — the run is
419	/// publish-only (bookmark + remote), which is the trapezoid
420	/// recipe's final step.
421	fn stage_message(root: &Path, params: &PushParams) -> Result<Run, Box<dyn std::error::Error>> {
422	    let bot = bot_path(root)?;
423	    // Both sides resolve their chid the same way: `@` when the
424	    // working copy has changes (it becomes `@-` once committed),
425	    // else the existing `@-` (which stays put, because that side's
426	    // commit stage skips). Taking `@` unconditionally on the work
427	    // side is what minted an empty stamped duplicate in bugs.md #4.
428	    let work_had_changes = !jj::is_empty(root, "@")?;
429	    let work_ref = if work_had_changes { "@" } else { "@-" };
430	    let work_chid = jj::chid_of(root, work_ref)?;
431	    let bot_had_changes = !jj::is_empty(&bot, "@")?;
432	    let bot_ref = if bot_had_changes { "@" } else { "@-" };
433	    let bot_chid = jj::chid_of(&bot, bot_ref)?;
434	    let will_commit = work_had_changes || bot_had_changes;
435	
436	    let (title, body) = match (params.title.clone(), params.body.clone()) {
437	        (Some(t), Some(b)) => (t, b),
438	        _ if !will_commit => {
439	            info!("push message: skip (neither repo has pending changes)");
440	            (String::new(), String::new())
441	        }
442	        _ => {
443	            if params.yes {
444	                return Err("push message: --yes given but --title/--body missing \
445	                            — pass both flags or run interactively."
446	                    .into());
447	            }
448	            if params.dry_run {
449	                return Err("push message: --dry-run given but --title/--body missing \
450	                            — pass both flags so dry-run has a message to preview."
451	                    .into());
452	            }
453	            if !is_stdin_tty() {
454	                return Err("push message: stdin is not a tty and no --title/--body \
455	                            supplied; cannot launch $EDITOR in a non-interactive \
456	                            context. Pass --title and --body, or run interactively."
457	                    .into());
458	            }
459	            compose_message_via_editor()?
460	        }
461	    };
462	
463	    info!(
464	        "push message: title=\"{}\", work_chid={work_chid}, bot_chid={bot_chid}, work_had_changes={work_had_changes}, bot_had_changes={bot_had_changes}",
465	        title.lines().next().unwrap_or("") // OK: obvious
466	    );
467	    Ok(Run {
468	        title,
469	        body,
470	        work_chid,
471	        bot_chid,
472	        bot_had_changes,
473	    })
474	}
475	
476	/// Launch `$EDITOR` (falling back to `vi`) on a scratch template,
477	/// then parse the saved content into a `(title, body)` tuple. Lines
478	/// starting with `#` are treated as comments and stripped. Empty
479	/// input aborts the push.
480	///
481	/// The template lives in the system temp dir, keyed by pid: with no
482	/// state dir left to put it in, and the file being read back within
483	/// the same call, it never needs to outlive the process.
484	fn compose_message_via_editor() -> Result<(String, String), Box<dyn std::error::Error>> {
485	    let editor = std::env::var("EDITOR")
486	        .or_else(|_| std::env::var("VISUAL"))
487	        .unwrap_or_else(|_| "vi".to_string()); // OK: POSIX fallback when nothing is configured
488	    let msg_path =
489	        std::env::temp_dir().join(format!("vc-x1-push-message-{}.txt", std::process::id()));
490	    let template = "\
491	# Leave as-is to abort. Enter the Title on the first line,
492	# optionally followed by the Body on subsequent lines. The
493	# blank line between Title and Body is inserted automatically,
494	# and the ochid trailer is appended per-repo automatically —
495	# don't add either here.
496	# Lines starting with `#` are ignored.
497	";
498	    fs::write(&msg_path, template)?;
499	    info!("push message: launching {editor} on {}", msg_path.display());
500	    let status = std::process::Command::new(&editor)
501	        .arg(&msg_path)
502	        .status()
503	        .map_err(|e| format!("failed to launch {editor}: {e}"))?;
504	    if !status.success() {
505	        return Err(format!("{editor} exited non-zero ({status})").into());
506	    }
507	    let content = fs::read_to_string(&msg_path)?;
508	    let _ = fs::remove_file(&msg_path);
509	    parse_message(&content)
510	        .ok_or_else(|| "push message: template was left empty or all-comments — aborting".into())
511	}
512	
513	/// Parse the editor-saved message into `(title, body)`. Strips
514	/// `#`-prefixed comment lines, trims surrounding blanks, and treats
515	/// the first non-comment line as the title with everything after as
516	/// the body (a blank line between is allowed but not required —
517	/// the commit stages insert the title/body separator themselves).
518	/// Returns `None` when the message has no non-comment content.
519	fn parse_message(raw: &str) -> Option<(String, String)> {
520	    let mut meaningful = String::new();
521	    for line in raw.lines() {
522	        let trimmed_left = line.trim_start();
523	        if trimmed_left.starts_with('#') {
524	            continue;
525	        }
526	        meaningful.push_str(line);
527	        meaningful.push('\n');
528	    }
529	    let trimmed = meaningful.trim();
530	    if trimmed.is_empty() {
531	        return None;
532	    }
533	    let mut lines = trimmed.lines();
534	    let title = lines.next().unwrap_or("").trim().to_string(); // OK: trimmed non-empty ⇒ first line exists
535	    let body = lines.collect::<Vec<_>>().join("\n").trim().to_string();
536	    if title.is_empty() {
537	        return None;
538	    }
539	    Some((title, body))
540	}
541	
542	/// Commit work repo with `title` / `body` and the `ochid:` trailer
543	/// pointing at `.claude`'s chid, or skip when the working copy has
544	/// nothing pending — the same rule `stage_commit_bot` follows.
545	///
546	/// Skipping matters in two situations:
547	///
548	/// - The rung was committed by hand before invoking push. Committing
549	///   the empty `@` anyway minted a stamped empty duplicate on top of
550	///   the real commit (bugs.md #4).
551	/// - A publish-only run, where the commits already exist and only
552	///   the bookmark and the remote still need advancing — the
553	///   trapezoid recipe's final step.
554	///
555	/// In both cases the existing top commit is published as-is; push
556	/// does not rewrite a description it didn't author.
557	fn stage_commit_work(
558	    ctx: &mut Context,
559	    root: &Path,
560	    run_msg: &Run,
561	    params: &PushParams,
562	) -> Result<(), Box<dyn std::error::Error>> {
563	    if jj::is_empty(root, "@")? {
564	        warn!(
565	            "push commit-work: skip (work repo had no pending changes); \
566	             the supplied message is not applied — the existing top \
567	             commit is published as-is"
568	        );
569	        return Ok(());
570	    }
571	    let (title, body) = (&run_msg.title, &run_msg.body);
572	    let bot_prefix = crate::desc_helpers::ochid_prefix_for(&bot_path(root)?)?;
573	    let body_with_trailer = format!("{body}\n\nochid: {bot_prefix}{}", run_msg.bot_chid);
574	    let work_arg = root.to_string_lossy();
575	    if params.dry_run {
576	        info!(
577	            "push commit-work: [dry-run] would run jj commit -R {work_arg} -m \"{title}\" -m <body+ochid>"
578	        );
579	        return Ok(());
580	    }
581	    info!("push commit-work: commit -R {work_arg}");
582	    ctx.session(root)?
583	        .commit(&format!("{title}\n\n{body_with_trailer}"))?;
584	    Ok(())
585	}
586	
587	/// Commit `.claude` with the same title/body and the ochid trailer
588	/// pointing at the work commit's chid, or skip if `.claude` had no
589	/// pending changes.
590	fn stage_commit_bot(
591	    ctx: &mut Context,
592	    root: &Path,
593	    run_msg: &Run,
594	    params: &PushParams,
595	) -> Result<(), Box<dyn std::error::Error>> {
596	    if !run_msg.bot_had_changes {
597	        info!("push commit-bot: skip (.claude had no pending changes)");
598	        return Ok(());
599	    }
600	    let (title, body) = (&run_msg.title, &run_msg.body);
601	    let body_with_trailer = format!("{body}\n\nochid: /{}", run_msg.work_chid);
602	    let bot = bot_path(root)?;
603	    let bot_arg = bot.to_string_lossy();
604	    if params.dry_run {
605	        info!(
606	            "push commit-bot: [dry-run] would run jj commit -R {bot_arg} -m \"{title}\" -m <body+ochid>"
607	        );
608	        return Ok(());
609	    }
610	    info!("push commit-bot: commit -R {bot_arg}");
611	    ctx.session(&bot)?
612	        .commit(&format!("{title}\n\n{body_with_trailer}"))?;
613	    Ok(())
614	}
615	
616	/// Advance each repo's bookmark to its `@-`: the work repo advances
617	/// `state.bookmark`, the bot repo always advances
618	/// `BOT_BOOKMARK` (`main`) — a feature bookmark must never be
619	/// created in the linear-journal bot repo.
620	fn stage_bookmark_set(
621	    ctx: &mut Context,
622	    root: &Path,
623	    bookmark: &str,
624	    params: &PushParams,
625	) -> Result<(), Box<dyn std::error::Error>> {
626	    let bk = bookmark;
627	    let work_arg = root.to_string_lossy();
628	    let bot = bot_path(root)?;
629	    let bot_arg = bot.to_string_lossy();
630	    if params.dry_run {
631	        info!(
632	            "push bookmark-set: [dry-run] would run jj bookmark set {bk} -r @- -R {work_arg} / {BOT_BOOKMARK} -r @- -R {bot_arg}"
633	        );
634	        return Ok(());
635	    }
636	    info!(
637	        "push bookmark-set: bookmark set {bk} -r @- -R {work_arg} / {BOT_BOOKMARK} -r @- -R {bot_arg}"
638	    );
639	    ctx.session(root)?.bookmark_set(bk, "@-")?;
640	    ctx.session(&bot)?.bookmark_set(BOT_BOOKMARK, "@-")?;
641	    Ok(())
642	}
643	
644	/// Push the work repo's bookmark to origin.
645	///
646	/// Checks its own precondition — every remote ref for the bookmark
647	/// is tracked — which is where preflight's tracking check moved
648	/// when preflight was retired. A never-pushed bookmark has no
649	/// remote ref and passes; the check catches a ref that exists but
650	/// isn't tracked, which would otherwise push into a ref jj won't
651	/// follow afterwards.
652	///
653	/// Rerunning is safe without a guard of its own: `jj git push` on
654	/// an already-published bookmark reports nothing to do.
655	fn stage_push_work(
656	    ctx: &mut Context,
657	    root: &Path,
658	    bookmark: &str,
659	    params: &PushParams,
660	) -> Result<(), Box<dyn std::error::Error>> {
661	    let bk = bookmark;
662	    let work_arg = root.to_string_lossy();
663	    if params.dry_run {
664	        info!("push push-work: [dry-run] would run jj git push --bookmark {bk} -R {work_arg}");
665	        return Ok(());
666	    }
667	    crate::common::verify_tracking(root, bk)?;
668	    info!("push push-work: git push --bookmark {bk} -R {work_arg}");
669	    ctx.session(root)?.git_push_bookmark(bk)?;
670	    Ok(())
671	}
672	
673	/// Squash-push `.claude` in-process, always pushing
674	/// `BOT_BOOKMARK` (`main`) — the bot repo's bookmark is
675	/// pinned, so the work-repo bookmark plays no part here.
676	///
677	/// - Squashes the tail (session writes that landed since
678	///   `commit-bot`) into the bot commit, then pushes — via
679	///   `squash_push::squash_push`, so the ochid-drop guard
680	///   applies and a failure is a visible push failure.
681	/// - In-process since 0.69.0-1 (the stage's detached child died
682	///   silently at sandbox teardown — the loss diagnosed in
683	///   0.68.1).
684	/// - `--no-squash-push` turns this stage into a no-op so the
685	///   squash+push can be run manually.
686	fn stage_squash_push_bot(
687	    ctx: &mut Context,
688	    root: &Path,
689	    params: &PushParams,
690	) -> Result<(), Box<dyn std::error::Error>> {
691	    let bk = BOT_BOOKMARK;
692	    let bot = bot_path(root)?;
693	    let bot_arg = bot.to_string_lossy();
694	    if params.dry_run {
695	        info!(
696	            "push squash-push-bot: [dry-run] would squash @ -> @- and push {bk} in {bot_arg} (in-process)"
697	        );
698	        return Ok(());
699	    }
700	    info!("push squash-push-bot: squash @ -> @- + push {bk} -R {bot_arg} (in-process)");
701	    let sp = crate::squash_push::SquashPushParams {
702	        repo: bot.clone(),
703	        squash: SquashSpec {
704	            source: "@".to_string(),
705	            target: "@-".to_string(),
706	        },
707	        bookmark: bk.to_string(),
708	        // Mid-push the mismatch is the normal state (bookmark-set
709	        // just moved main; this stage publishes it) — don't report
710	        // a lost publish.
711	        report_publish_state: false,
712	    };
713	    crate::squash_push::squash_push(ctx, &sp)
714	}
715	
716	/// Verify the world matches what the stages claim to have done.
717	///
718	/// Runs after the last stage and confirms the post-conditions are
719	/// real — directly addresses the 0.37.1 false-success symptom (push
720	/// declared "completed all stages" while the working copy still held
721	/// uncommitted changes).
722	///
723	/// Three checks:
724	///
725	/// 1. Work's bookmark is at a commit whose chid matches the run's
726	///    `work_chid`.
727	/// 2. Work's working copy has no uncommitted changes (commit-work
728	///    should have captured anything that was there).
729	/// 3. `.claude`'s bookmark is at the run's `bot_chid`.
730	///    `.claude`'s working copy (`@`) may legitimately have new
731	///    session writes that landed after squash-push-bot's squash —
732	///    the tail rides into the next cycle's commit — so no
733	///    working-copy-clean check on `.claude`.
734	///
735	/// On any mismatch: returns `Err`. The caller surfaces it as a loud
736	/// warning rather than blocking — push has already crossed the
737	/// remote boundary, work is live on origin, and the warning prompts
738	/// the user to investigate.
739	fn verify_completion(
740	    root: &Path,
741	    bookmark: &str,
742	    run_msg: &Run,
743	) -> Result<(), Box<dyn std::error::Error>> {
744	    let root_str = root.to_string_lossy();
745	    let cwd = Path::new(".");
746	
747	    // 1. work bookmark at the run's work_chid.
748	    let actual = jj::chid_of(root, bookmark)?;
749	    if actual != run_msg.work_chid {
750	        return Err(format!(
751	            "completion sanity: work bookmark '{bookmark}' is at chid '{actual}' but \
752	             this run committed '{}'.",
753	            run_msg.work_chid
754	        )
755	        .into());
756	    }
757	
758	    // 2. work working copy (`@`) clean (no uncommitted changes). Use the `empty`
759	    // template — `jj diff --stat` always emits a "0 files changed"
760	    // line even when clean, so plain output-emptiness check would
761	    // false-positive.
762	    if !jj::is_empty(root, "@")? {
763	        let wc_diff = run("jj", &["diff", "--stat", "-r", "@", "-R", &root_str], cwd)?;
764	        return Err(format!(
765	            "completion sanity: work working copy has uncommitted changes (push completed \
766	             but working copy dirty?). Diff stat:\n{wc_diff}"
767	        )
768	        .into());
769	    }
770	
771	    // 3. .claude's pinned bookmark (main) at the run's bot_chid.
772	    let actual = jj::chid_of(&bot_path(root)?, BOT_BOOKMARK)?;
773	    if actual != run_msg.bot_chid {
774	        return Err(format!(
775	            "completion sanity: .claude bookmark '{BOT_BOOKMARK}' is at chid \
776	             '{actual}' but this run committed '{}'.",
777	            run_msg.bot_chid
778	        )
779	        .into());
780	    }
781	
782	    Ok(())
783	}
784	
785	#[cfg(test)]
786	mod tests;
787	
788	#[cfg(test)]
789	mod integration_tests;
