83	/// Load `repo`'s snapshot, `Ok(None)` when absent (no failed or
84	/// in-flight sync), `Err` when present but unreadable / wrong
85	/// version.
86	pub fn load(repo: &Path) -> Result<Option<SyncState>, Box<dyn std::error::Error>> {
87	    let path = state_path(repo);
88	    if !path.exists() {
89	        return Ok(None);
90	    }
91	    let map = toml_load(&path)?;
92	    let require = |k: &str| -> Result<String, Box<dyn std::error::Error>> {
93	        map.get(k)
94	            .cloned()
95	            .ok_or_else(|| format!("{}: missing key '{k}'", path.display()).into())
96	    };
97	    let version: u32 = require("sync-state.version")?.parse()?;
98	    if version != STATE_FORMAT_VERSION {
