100	            "{}: unsupported sync-state version {version} (expected {STATE_FORMAT_VERSION})",
101	            path.display()
102	        )
103	        .into());
104	    }
105	    Ok(Some(SyncState {
106	        version,
107	        op_id: require("sync-state.op_id")?,
108	        bookmark: require("sync-state.bookmark")?,
109	        remote: require("sync-state.remote")?,
110	        started_at: require("sync-state.started_at")?,
111	    }))
112	}
113	
114	/// Remove `repo`'s snapshot if present (success path / post-revert).
115	pub fn clear(repo: &Path) -> Result<(), Box<dyn std::error::Error>> {
116	    let path = state_path(repo);
117	    if path.exists() {
118	        fs::remove_file(&path)?;
119	        debug!("sync: cleared state at {}", path.display());
120	    }
121	    Ok(())
122	}
123	
124	#[cfg(test)]
125	mod tests {
126	    use super::*;
127	    use crate::test_helpers::unique_base;
128	
129	    /// save -> load round-trips every field; clear removes the file.
130	    #[test]
131	    fn save_load_clear_roundtrip() {
132	        let repo = unique_base("sync-state");
133	        fs::create_dir_all(&repo).expect("mkdir fixture repo");
134	        save(&repo, "abcdef123456", "main", "origin").expect("save");
135	        let st = load(&repo).expect("load").expect("state present");
136	        assert_eq!(st.version, STATE_FORMAT_VERSION);
137	        assert_eq!(st.op_id, "abcdef123456");
138	        assert_eq!(st.bookmark, "main");
139	        assert_eq!(st.remote, "origin");
140	        assert!(!st.started_at.is_empty());
141	        clear(&repo).expect("clear");
142	        assert!(load(&repo).expect("load after clear").is_none());
143	        fs::remove_dir_all(&repo).ok();
144	    }
145	
146	    /// Absent file loads as `None`.
147	    #[test]
148	    fn load_absent_is_none() {
149	        let repo = unique_base("sync-state-absent");
150	        fs::create_dir_all(&repo).expect("mkdir fixture repo");
151	        assert!(load(&repo).expect("load").is_none());
152	        fs::remove_dir_all(&repo).ok();
153	    }
154	}
