pub fn clear(repo: &Path) -> Result<(), Box<dyn std::error::Error>> {
    let path = state_path(repo);
    if path.exists() {
        fs::remove_file(&path)?;
        debug!("sync: cleared state at {}", path.display());
    }
    Ok(())
}

